// The whole rhythm system. The gap above a block is a function of
// what came before it — that is the entire trick.
function gapClass(prev, block) {
    if (!prev) return '';

    if (prev.kind === 'heading') {
        // A heading and its body are one unit.
        return block.kind === 'prose' ? TIGHT : LOOSE;
    }

    if (prev.kind === 'prose' && block.kind === 'prose') return CLOSE;

    return ''; // inherit the section-level gap
}
